<script module lang="ts">
/**
 * A short text hint shown on hover or focus (`design/components/tooltip.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/tooltip.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type Snippet } from 'svelte'

import * as zag from '@zag-js/tooltip'
import { useMachine } from '@zag-js/svelte'

import {
  Portal,
  TOOLTIP_DELAY_MS,
  TOOLTIP_SKIP_DELAY_MS,
  anchorProps,
  attributes,
  joinSlot,
  normalizeProps,
  syncTriggerAnchor,
  useDirection,
  watchEffect,
} from '@polymorph/svelte'
import { usePresence } from '@polymorph/svelte/motion'
import styles from '@polymorph/recipes/overlays/tooltip.module.css'

export type TooltipAlign = NonNullable<TooltipProps['align']>

export type TooltipSide = NonNullable<TooltipProps['side']>

export interface TooltipProps {
  align?: 'start' | 'center' | 'end'
  /**
   * One focusable element; a tooltip on a disabled control can never be read.
   */
  children: Snippet
  content: string
  /**
   * Opens on mount, for galleries and tests.
   */
  defaultOpen?: boolean
  side?: 'bottom' | 'top' | 'right' | 'left'
}
</script>

<script lang="ts">
let { align = 'center', children, content, defaultOpen, side = 'top' }: TooltipProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({}))
let anchor = $state<HTMLElement | null>(null)
let bubble = $state<HTMLElement | null>(null)
const documentDirection = useDirection()
const service = useMachine(
  zag.machine,
  () =>
    ({
      id: uid,
      dir: documentDirection.current,
      defaultOpen: defaultOpen,
      openDelay: TOOLTIP_DELAY_MS,
      closeDelay: TOOLTIP_SKIP_DELAY_MS,
      positioning: { placement: align === 'center' ? side : `${side}-${align}`, gutter: 0 },
    }) as Partial<zag.Props>,
)
const api = $derived(zag.connect(service, normalizeProps))
const present = usePresence(
  () => api.open,
  () => bubble,
  'tooltip.bubble',
  {
    get side() {
      return side
    },
    get align() {
      return align
    },
  },
)
const effect1 = () => {
  syncTriggerAnchor(anchor, api.getTriggerProps(), api.open, false)
}
watchEffect(effect1, { watch: () => api.open })
</script>

{@render joined.start?.()
}{#if joined.shown
  }<span
    bind:this={anchor}
    {...attributes(anchorProps(api.getTriggerProps()))}
    class={styles.anchor}
    data-tooltip-part="trigger"
    >{@render children?.()
  }</span
  ><Portal
    >{#if present.current
      }<div {...attributes(api.getPositionerProps())}
        ><div
          bind:this={bubble}
          {...attributes(api.getContentProps())}
          class={styles.bubble}
          style:--radix-tooltip-content-available-width={'var(--available-width)'}
          hidden={undefined}
          data-state={api.open ? 'delayed-open' : 'closed'}
          data-member="tooltip"
          >{content
        }</div
      ></div
    >{/if
  }</Portal
>{/if
}{@render joined.end?.()}
